import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "vite";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
// Vite's source-region comments are relative to the process working directory.
// Keep generated bytes identical for repository and package invocations.
process.chdir(root);
let generated = "// Generated by scripts/generate-sqlite-workers.mjs; DO NOT EDIT.\n";
// Bundle maintained SDK code before converting it to a string. Runtime
// Function.toString() loses helpers introduced by source loaders and bundlers.
for (const [name, entry] of [
  ["sqliteWorkerSource", "sqliteWorkerProgramV4.ts"],
  ["poolStorageWorkerSource", "sqlitePoolWorkerProgramV4.ts"],
]) {
  const result = await build({
    configFile: false,
    root,
    logLevel: "error",
    build: {
      ssr: path.join(root, "src/node", entry),
      write: false,
      minify: false,
      target: "es2022",
      rollupOptions: { output: { format: "cjs", codeSplitting: false } },
    },
  });
  const output = (Array.isArray(result) ? result[0] : result).output;
  if (output.length !== 1 || output[0].type !== "chunk" || output[0].dynamicImports.length !== 0 ||
      output[0].imports.some(specifier => !specifier.startsWith("node:"))) {
    throw new Error(`${name} must contain only fixed SDK code and Node builtins`);
  }
  generated += `export const ${name} = ${JSON.stringify(output[0].code)};\n`;
}
const target = path.join(root, "src/generated/sqliteWorkers.ts");
if (process.argv.includes("--check")) {
  if (await readFile(target, "utf8") !== generated) throw new Error("SQLite worker source drift");
} else {
  await writeFile(target, generated);
}
